  const legacyHouseIds = new Set(["house-silveredge", "house-swiftwood-duskwood", "swiftwood-duskwood", "house-darkblade", "house-darkhaven", "house-nightwind", "house-seisen", "dragonkin-rei-line", "raiku-makai-line"]);
